// GENERATED by scripts/build-courses.ts from src/lib/courses/content — edit those files, then run: npm run courses
import type { LessonText } from '../types';
const text: LessonText[][] = [[{"say":"Trigonometry starts with right triangles. Three ratios connect angles to side lengths.","blocks":[{"t":"key","text":"SOH-CAH-TOA: sin θ = opposite/hypotenuse, cos θ = adjacent/hypotenuse, tan θ = opposite/adjacent."},{"t":"p","text":"The reciprocal ratios are cosecant (csc = 1/sin), secant (sec = 1/cos) and cotangent (cot = 1/tan)."},{"t":"ex","problem":"In a right triangle with legs 7 and 24 and hypotenuse 25, find sin and tan of the angle opposite the side of 7.","steps":["sin = 7/25","tan = 7/24"],"answer":"sin θ = 7/25, tan θ = 7/24"},{"t":"p","text":"For complementary angles, sin θ = cos(90° − θ)."}]},{"say":"With trig ratios, you can find any missing side or angle of a right triangle.","blocks":[{"t":"p","text":"To find a side: write the ratio that uses the known side and the unknown side, then solve."},{"t":"p","text":"To find an angle: use an inverse function, like θ = tan⁻¹(opposite/adjacent)."},{"t":"ex","problem":"A ladder makes a 70° angle with the ground and reaches 12 ft up a wall. How long is the ladder?","steps":["sin 70° = 12/L","L = 12/sin 70° ≈ 12/0.940"],"answer":"about 12.8 ft"},{"t":"key","text":"Special right triangles give exact values: 45-45-90 has sides 1 : 1 : √2, and 30-60-90 has sides 1 : √3 : 2."},{"t":"p","text":"Angle of elevation is measured up from horizontal; angle of depression is measured down from horizontal."}]}],[{"say":"To go beyond right triangles, we measure angles in radians and place them on the coordinate plane.","blocks":[{"t":"p","text":"An angle in standard position starts on the positive x-axis. Counterclockwise rotation is positive; clockwise is negative."},{"t":"key","text":"π radians = 180°. To convert degrees to radians, multiply by π/180; radians to degrees, multiply by 180/π."},{"t":"ex","problem":"Convert 135° to radians.","steps":["135 × π/180 = 3π/4"],"answer":"3π/4"},{"t":"p","text":"Coterminal angles share a terminal side; add or subtract 360° (or 2π). Arc length s = rθ when θ is in radians."},{"t":"tip","text":"Memorize the key conversions: 30° = π/6, 45° = π/4, 60° = π/3, 90° = π/2 and 180° = π."}]},{"say":"The unit circle is trig's master map. Every angle's sine and cosine can be read right off it.","blocks":[{"t":"key","text":"On the unit circle (radius 1), the point at angle θ is (cos θ, sin θ)."},{"t":"p","text":"Key values in Quadrant I: (√3/2, 1/2) at π/6, (√2/2, √2/2) at π/4, (1/2, √3/2) at π/3."},{"t":"p","text":"Use reference angles and signs by quadrant: Quadrant I all positive; II sine positive; III tangent positive; IV cosine positive."},{"t":"ex","problem":"Find cos(7π/6).","steps":["7π/6 is in Quadrant III, reference angle π/6","cos π/6 = √3/2, and cosine is negative in Quadrant III"],"answer":"−√3/2"}]}],[{"say":"Sine and cosine graphs are smooth waves. Learn their parts and you can sketch any transformation.","blocks":[{"t":"key","text":"y = A sin(B(x − C)) + D has amplitude |A|, period 2π/B, phase shift C, and vertical shift (midline) D."},{"t":"p","text":"y = sin x starts at 0 and rises; y = cos x starts at its maximum. Both have period 2π and range [−1, 1]."},{"t":"ex","problem":"Describe y = 2 cos(3x) − 1.","steps":["Amplitude 2; period 2π/3","Midline y = −1, so it ranges from −3 to 1"],"answer":"amplitude 2, period 2π/3, midline y = −1"}]},{"say":"Tangent and the reciprocal functions have asymptotes, making their graphs look very different from sine and cosine.","blocks":[{"t":"key","text":"y = tan x has period π and vertical asymptotes where cos x = 0 (x = π/2 + kπ). It passes through the origin."},{"t":"p","text":"Secant (1/cos) has asymptotes where cos x = 0; cosecant (1/sin) has asymptotes where sin x = 0. Their graphs are U-shaped curves between asymptotes."},{"t":"ex","problem":"Where are the asymptotes of y = tan x between 0 and 2π?","steps":["cos x = 0 at π/2 and 3π/2"],"answer":"x = π/2 and x = 3π/2"},{"t":"p","text":"Inverse trig graphs: arcsin and arccos are defined on [−1, 1]; arctan is defined for all real numbers with horizontal asymptotes at ±π/2."}]}],[{"say":"Identities are equations true for every angle. They help simplify expressions and solve equations.","blocks":[{"t":"key","text":"Pythagorean identity: sin²θ + cos²θ = 1. Also 1 + tan²θ = sec²θ and 1 + cot²θ = csc²θ."},{"t":"p","text":"Quotient identities: tan θ = sin θ/cos θ; cot θ = cos θ/sin θ."},{"t":"p","text":"Sum formula: sin(A + B) = sin A cos B + cos A sin B. Double angle: sin 2θ = 2 sin θ cos θ; cos 2θ = cos²θ − sin²θ."},{"t":"ex","problem":"Simplify sin θ · cot θ.","steps":["cot θ = cos θ/sin θ","sin θ · cos θ/sin θ"],"answer":"cos θ"},{"t":"tip","text":"When verifying an identity, rewrite everything in terms of sine and cosine."}]},{"say":"Trig equations have many solutions because trig functions repeat. And two laws solve any triangle.","blocks":[{"t":"p","text":"To solve a trig equation, isolate the trig function, find solutions in one cycle, then add multiples of the period."},{"t":"ex","problem":"Solve 2 sin x − √3 = 0 on [0, 2π).","steps":["sin x = √3/2"],"answer":"x = π/3 or 2π/3"},{"t":"key","text":"Law of Sines: a/sin A = b/sin B = c/sin C. Law of Cosines: c² = a² + b² − 2ab cos C."},{"t":"p","text":"Use Law of Sines when you know an angle and its opposite side; use Law of Cosines for SAS or SSS."}]}]];
export default text;
